// Materi Lengkap — Dasar-dasar Sistem Informasi. Isi modul diperluas dengan penjelasan, contoh, dan rujukan umum (O'Brien, McLeod, Laudon, Jogiyanto).
const A = (title, html, label) => ({ type: "article", label, title, html });
const tip = (heading, html, tone) => ({ type: "callout", tone: tone || "tip", heading, html });

const D = require("./dg_dsi.js");
const M = {
  p1: [
    A("Kenapa Harus Mulai dari “Sistem”?", `<p>Mata kuliah ini bernama <strong>Sistem Informasi</strong>. Sebelum memahami “informasi”, kita perlu paham dulu apa itu <strong>sistem</strong>, karena cara berpikir sistem akan dipakai di semua pertemuan berikutnya: saat membahas komponen SI (P3), tipe SI (P4), CBIS (P5), sampai pengelolaan data (P7).</p>
<p>Cara berpikir sistem (<em>system thinking</em>) artinya melihat sesuatu sebagai <strong>kumpulan bagian yang saling memengaruhi</strong>, bukan bagian-bagian yang berdiri sendiri. Contoh sederhana: tubuh manusia. Jantung, paru-paru, dan darah masing-masing punya fungsi, tetapi baru “hidup” ketika bekerja bersama. Kalau satu bagian rusak, bagian lain ikut terganggu.</p>`, "Bagian 1 • Pengantar"),
    A("Definisi Sistem", `<p>Menurut <strong>McLeod (2003)</strong>, sistem adalah <strong>satu set elemen atau komponen yang saling berinteraksi untuk mencapai tujuan tertentu</strong>. Ada tiga kata kunci yang harus selalu kamu ingat:</p>
<ol><li><strong>Elemen/komponen</strong>: bagian-bagian penyusunnya. Di kampus: mahasiswa, dosen, ruang kelas, LMS, jadwal.</li><li><strong>Interaksi</strong>: bagian-bagian itu saling berhubungan. Dosen mengunggah materi, mahasiswa mengerjakan tugas, LMS menghitung nilai.</li><li><strong>Tujuan</strong>: semua interaksi itu diarahkan ke satu hasil. Di kampus: menghasilkan lulusan yang kompeten.</li></ol>
<p>Modul menambahkan bahwa sistem adalah <strong>konsep</strong> yang dibuat untuk memudahkan pemahaman. Karena itu, orang yang mempelajari sistem perlu <strong>menyepakati</strong> tiga hal: apa saja <strong>elemennya</strong>, bagaimana <strong>hubungan antar elemen</strong>, dan di mana <strong>batas-batasnya</strong>. Contohnya, “sistem perpustakaan” bisa didefinisikan hanya sebagai peminjaman buku, atau diperluas sampai pengadaan buku. Keduanya sah, asal disepakati di awal.</p>
<p>Sistem juga memiliki <strong>identitas pembeda</strong>: rakitan komponen yang berbeda-beda tetapi saling terkait erat, sehingga bisa dikenali sebagai satu kesatuan (misalnya “sistem penggajian”, bukan sekadar “komputer + karyawan”).</p>`, "Bagian 2"),
    A("Enam Karakteristik Sistem", `<p>Modul menyebut enam karakteristik yang dimiliki sistem. Bayangkan sebuah <strong>dapur restoran</strong> sebagai sistem:</p>
<ul><li><strong>Boundary (batasan)</strong>: pemisah antara sistem dan lingkungannya. Dapur dibatasi pintu dapur; meja makan tamu sudah di luar sistem dapur. Batas ini menentukan <strong>ruang lingkup</strong> dan <strong>kemampuan</strong> sistem: dapur tidak mengurus parkir.</li><li><strong>Inputs (masukan)</strong>: yang masuk untuk diolah. Di dapur: bahan makanan dan pesanan. Pada sistem informasi, input berupa <strong>data transaksi</strong> (pesanan, pembayaran), <strong>data non-transaksi</strong> (data menu, data pegawai), dan <strong>instruksi</strong> (perintah kepada sistem).</li><li><strong>Processing (proses)</strong>: pengolahan input menjadi output yang diharapkan. Di dapur: memasak.</li><li><strong>Outputs (keluaran)</strong>: hasil yang dipakai pengguna. Di dapur: hidangan. Pada SI: <strong>informasi, saran, laporan tercetak</strong>.</li><li><strong>Controls (kendali)</strong>: kegiatan mengamati dan mengawasi agar sistem berjalan sesuai rencana. Di dapur: kepala koki mencicipi dan memeriksa standar porsi. Pada SI: mengawasi fungsi perencanaan informasi, koordinasi, dan transformasi.</li><li><strong>Feedback (umpan balik)</strong>: informasi tentang hasil yang dikembalikan ke sistem sebagai bahan perbaikan. Di dapur: komentar tamu “terlalu asin” membuat resep disesuaikan.</li></ul>
<p>Hubungan keenamnya bisa dibaca seperti kalimat: <em>input diproses menjadi output, prosesnya diawasi oleh control, hasilnya dikembalikan lewat feedback, dan semua itu terjadi di dalam boundary</em>.</p>`, "Bagian 3"),
    tip("Catatan tentang definisi input di modul", "Modul sempat menyebut input sebagai “bagian dari sistem mikroprosesor untuk menghubungkan perangkat luar dengan komputer”. Kalimat itu sebenarnya definisi <strong>port/perangkat input pada komputer</strong>. Untuk konsep sistem, pakai pengertian umum: <strong>input adalah segala sesuatu yang masuk ke sistem untuk diolah</strong>.", "warn"),
    A("Umpan Balik Negatif dan Positif", `<p>Kata “negatif” dan “positif” di sini <strong>bukan berarti buruk dan baik</strong>. Keduanya sama-sama berguna, hanya arahnya berbeda.</p>
<ul><li><strong>Umpan balik negatif</strong> bertujuan <strong>mengurangi penyimpangan</strong> dari jalur standar yang bisa menghambat tujuan. Ia bekerja seperti rem atau setir: mengembalikan sistem ke jalurnya. Contoh: termostat AC menyala ketika suhu naik melewati 24°C; nilai kuis di bawah KKM membuat dosen memberi remedial; pengeluaran bulan ini melebihi anggaran sehingga belanja bulan depan dikurangi.</li><li><strong>Umpan balik positif</strong> digunakan untuk <strong>menambah kekuatan gerak sistem</strong> agar tujuan makin cepat tercapai. Ia bekerja seperti pedal gas. Contoh: produk laris membuat toko menambah stok dan iklan; video yang banyak ditonton makin sering direkomendasikan.</li></ul>
<p>Cara cepat membedakan di soal: jika ada kata <strong>mengurangi penyimpangan / kembali ke standar / koreksi</strong> → negatif. Jika ada kata <strong>memperkuat / mempercepat / menambah</strong> → positif.</p>`, "Bagian 4"),
    A("Dua Cara Mempelajari Sistem", `<p>Saat menganalisis sistem nyata (misalnya ketika kelak kamu menjadi analis sistem), ada dua pendekatan menurut modul:</p>
<ol><li><strong>Menentukan batas (boundaries) terlebih dahulu.</strong> Caranya dengan melihat elemen yang <strong>interaksinya sangat intens</strong> (sering berhubungan), atau elemen yang <strong>lebih tunduk pada aturan</strong> sistem tersebut. Contoh: dalam sistem akademik, bagian akademik, dosen, dan mahasiswa berinteraksi sangat sering, sedangkan kantin kampus tidak; maka kantin berada di luar batas.</li><li><strong>Mempelajari semua elemen</strong> termasuk interaksinya. Pada cara ini <strong>tidak boleh ada elemen yang dibuang</strong> hanya demi penyederhanaan (<em>simplification</em>), karena elemen kecil bisa saja punya pengaruh besar.</li></ol>
<p>Itulah sebabnya opsi “melihat sedikit saja elemen yang terlibat” selalu salah di soal: ia bertentangan dengan cara kedua.</p>`, "Bagian 5"),
    A("➕ Pengayaan: Karakteristik Versi Jogiyanto", `<p>Buku-buku SI di Indonesia (terutama Jogiyanto, <em>Analisis dan Desain Sistem Informasi</em>) sering menyebut <strong>delapan</strong> karakteristik sistem. Selain yang ada di modul, ada:</p>
<ul><li><strong>Komponen (components)</strong>: subsistem yang membentuk sistem.</li><li><strong>Lingkungan luar (environment)</strong>: segala sesuatu di luar batas yang memengaruhi sistem, bisa menguntungkan (harus dijaga) atau merugikan (harus dikendalikan). Contoh untuk kampus: kebijakan kementerian, kondisi internet, kampus pesaing.</li><li><strong>Penghubung (interface)</strong>: media yang menghubungkan subsistem satu dengan yang lain, misalnya formulir KRS yang menghubungkan mahasiswa dengan bagian akademik.</li><li><strong>Sasaran/tujuan (objective/goal)</strong>: sistem tanpa tujuan tidak ada gunanya.</li></ul>
<p>Untuk ujian mata kuliah ini, hafalkan <strong>versi modul (6)</strong>. Versi Jogiyanto berguna supaya kamu tidak bingung bila bertemu soal dari sumber lain.</p>`, "Pengayaan"),
    A("➕ Pengayaan: Klasifikasi Sistem", `<p>Sistem juga bisa dikelompokkan berdasarkan sifatnya:</p>
<ul><li><strong>Abstrak vs fisik</strong>: sistem teologi atau sistem bilangan (abstrak) vs sistem komputer atau sistem transportasi (fisik).</li><li><strong>Alamiah vs buatan manusia</strong>: sistem tata surya (alamiah) vs sistem informasi (buatan manusia).</li><li><strong>Tertentu (deterministik) vs tak tentu (probabilistik)</strong>: program komputer yang hasilnya bisa diprediksi vs perilaku pasar.</li><li><strong>Tertutup vs terbuka</strong>: sistem terbuka menerima input dan mengeluarkan output ke lingkungan. Hampir semua SI di organisasi adalah <strong>sistem terbuka</strong>.</li></ul>
<p>Selain itu ada istilah <strong>subsistem</strong> (sistem di dalam sistem) dan <strong>supersistem</strong> (sistem yang lebih besar yang memuat sistem tersebut). Sistem akademik adalah subsistem dari sistem kampus; kampus adalah subsistem dari sistem pendidikan nasional.</p>`, "Pengayaan"),
    tip("Cek pemahaman", "Coba jelaskan aplikasi ojek online dengan 6 karakteristik: <strong>input</strong> (titik jemput & tujuan), <strong>processing</strong> (hitung tarif, cari driver), <strong>output</strong> (estimasi harga, nama driver), <strong>control</strong> (verifikasi akun, batas pembatalan), <strong>feedback</strong> (rating driver dipakai untuk menurunkan prioritas driver yang buruk → negatif), <strong>boundary</strong> (tidak mengurus servis motor driver). Kalau bisa menjelaskan ini, kamu sudah paham P1.")
  ],

  p2: [
    A("Data, Informasi, dan Pengetahuan Itu Berbeda", `<p>Dalam bahasa sehari-hari, “data” dan “informasi” sering dipakai bergantian. Dalam ilmu SI, keduanya <strong>berbeda tingkat pengolahannya</strong>. Pemahaman ini penting karena tugas utama sistem informasi adalah <strong>mengubah data menjadi informasi</strong>.</p>
<p>Bayangkan tangga tiga anak tangga: <strong>data</strong> di bawah, <strong>informasi</strong> di tengah, <strong>pengetahuan (knowledge)</strong> di atas. Setiap naik satu anak tangga, nilainya bertambah karena sudah diolah dan diberi makna.</p>`, "Bagian 1 • Pengantar"),
    A("Data", `<p>Data adalah <strong>kumpulan keterangan atau fakta, simbol</strong>, yang <strong>masih mentah</strong>. Data bisa langsung <strong>diamati atau diverifikasi</strong>, tetapi <strong>tidak memiliki makna yang melekat</strong>. Contoh dari modul: usia, nilai ujian, warna mobil, ukuran sepatu, jenis rambut.</p>
<p>Ambil contoh angka <strong>“78”</strong>. Itu data. Apakah 78 itu nilai ujian, berat badan, atau nomor rumah? Kita tidak tahu sebelum ada konteks. Itulah maksud “tidak bermakna melekat”.</p>
<p>Menurut modul, jenis data meliputi: <strong>data numerik</strong> (angka, huruf, dan karakter lain), <strong>data gambar</strong> (gambar grafis), <strong>data audio</strong> (suara, noise, tones), dan <strong>data video</strong> (gambar bergerak).</p>
<p>➕ Catatan istilah: secara teknis, data berisi huruf dan karakter lebih tepat disebut <strong>alfanumerik/teks</strong>, sedangkan numerik hanya angka. Pembagian lain yang umum adalah <strong>data kuantitatif</strong> (bisa dihitung: usia, nilai) dan <strong>kualitatif</strong> (kategori: warna, jenis rambut), serta <strong>data terstruktur</strong> (tabel) dan <strong>tidak terstruktur</strong> (foto, video, chat).</p>`, "Bagian 2"),
    A("Lima Cara Data Menjadi Informasi (5K)", `<p>Data baru bermakna setelah <strong>ditafsirkan</strong>. Modul menyebut lima cara, yang bersumber dari Davenport & Prusak. Ingat sebagai <strong>5K</strong>:</p>
<ol><li><strong>Kondensasi</strong>: meringkas data dan membuang kedalaman yang tidak dibutuhkan. Contoh: dari 40 kolom data mahasiswa, hanya diambil NIM, nama, dan nilai akhir.</li><li><strong>Kontekstualisasi</strong>: memahami <strong>mengapa data dikumpulkan</strong>. Contoh: data nilai ini dikumpulkan untuk evaluasi akreditasi, bukan untuk beasiswa, sehingga cara membacanya pun berbeda.</li><li><strong>Kalkulasi</strong>: menganalisa data sesuai kebutuhan. Contoh: menghitung rata-rata, persentase kelulusan.</li><li><strong>Kategorisasi</strong>: mengelompokkan hasil analisa menjadi kesatuan yang bermakna. Contoh: membagi mahasiswa menjadi “lulus” dan “remedial”.</li><li><strong>Koreksi</strong>: menghilangkan kesalahan selama proses analisa. Contoh: menghapus nilai yang terinput dua kali.</li></ol>
<p>Pengecoh yang sering muncul: <em>konsolidasi, kompilasi, konversi</em>. Ketiganya <strong>tidak</strong> termasuk 5K.</p>`, "Bagian 3"),
    A("Informasi", `<p>Informasi adalah <strong>kumpulan fakta yang terorganisir</strong>, yaitu <strong>hasil pemrosesan data</strong> sehingga <strong>memiliki arti dalam konteks tertentu</strong>. Contoh modul: informasi lulusan sebuah universitas pada periode tertentu, informasi cara membayar pajak kendaraan.</p>
<p>Melanjutkan contoh “78”: setelah diolah menjadi “<em>rata-rata nilai UTS kelas SI-A tahun 2026 adalah 78, naik 5 poin dari tahun lalu</em>”, angka itu menjadi informasi. Ada konteks (kelas, tahun), ada pengolahan (rata-rata, perbandingan), dan bisa dipakai mengambil keputusan.</p>
<p>➕ Informasi bersifat <strong>relatif</strong>: rekap nilai per kelas adalah informasi bagi dosen, tetapi menjadi <strong>data</strong> bagi kaprodi yang mengolahnya lagi menjadi rekap seluruh prodi.</p>`, "Bagian 4"),
    A("Sebelas Karakteristik Informasi yang Baik", `<p>Tidak semua informasi berguna. Modul menyebut 11 karakteristik yang membuat informasi <strong>bernilai bagi organisasi</strong>:</p>
<ul><li><strong>Accessible</strong>: mudah diakses <strong>pengguna yang berwenang</strong>, dalam format dan waktu yang tepat.</li><li><strong>Accurate</strong>: bebas kesalahan. Informasi tidak akurat sering berasal dari data input yang salah: <strong>Garbage In, Garbage Out (GIGO)</strong>.</li><li><strong>Complete</strong>: memuat fakta penting. Laporan investasi yang tidak memasukkan semua biaya penting dianggap tidak lengkap.</li><li><strong>Economical</strong>: biaya menghasilkannya sebanding dengan manfaatnya.</li><li><strong>Flexible</strong>: bisa dipakai untuk banyak kepentingan (data penjualan dipakai gudang, keuangan, pemasaran).</li><li><strong>Relevant</strong>: terkait dengan masalah yang sedang diputuskan.</li><li><strong>Reliable</strong>: dapat diandalkan; sumber dan metodenya terpercaya.</li><li><strong>Secure</strong>: aman dari pengguna yang tidak berhak.</li><li><strong>Simple</strong>: cukup sederhana; informasi yang terlalu rinci justru menyulitkan keputusan (<em>information overload</em>).</li><li><strong>Timely</strong>: tersedia saat dibutuhkan, tidak “basi”.</li><li><strong>Verifiable</strong>: bisa diuji dan dibuktikan kebenarannya.</li></ul>
<p>Jembatan keledai huruf awalnya: <strong>A-A-C-E-F-R-R-S-S-T-V</strong>. Hati-hati membedakan <em>accurate</em> (isinya benar), <em>reliable</em> (bisa diandalkan), dan <em>verifiable</em> (bisa dicek).</p>`, "Bagian 5"),
    A("Pengetahuan (Knowledge)", `<p>Knowledge adalah <strong>hasil pengolahan informasi sehingga menjadi sesuatu yang bermanfaat</strong>. Pengetahuan biasanya didasarkan pada <strong>pengalaman, persepsi, dan pendapat individual</strong>.</p>
<p>Contoh: informasi “penjualan payung naik 300% setiap Desember” dimiliki banyak orang. Pemilik toko yang sudah bertahun-tahun berjualan <strong>tahu</strong> bahwa ia harus memesan stok payung sejak Oktober karena pemasok sering terlambat. Itulah pengetahuan: informasi yang sudah dipadukan dengan pengalaman sehingga bisa langsung dipakai bertindak.</p>
<p>➕ Dalam manajemen pengetahuan dikenal dua jenis: <strong>tacit knowledge</strong> (ada di kepala orang, sulit ditulis, seperti “feeling” koki senior) dan <strong>explicit knowledge</strong> (sudah didokumentasikan, seperti SOP dan resep tertulis).</p>`, "Bagian 6"),
    A("➕ Pengayaan: Piramida DIKW dan Nilai Informasi", `<p>Banyak buku melanjutkan tangga data–informasi–pengetahuan menjadi <strong>DIKW</strong>: <strong>Data → Information → Knowledge → Wisdom</strong>. <em>Wisdom</em> adalah kebijaksanaan menggunakan pengetahuan untuk memutuskan hal yang tepat, termasuk mempertimbangkan etika dan jangka panjang.</p>
<p>➕ <strong>Nilai informasi</strong> sering dirumuskan sebagai <em>manfaat dikurangi biaya</em> memperolehnya. Ini sejalan dengan karakteristik <em>economical</em>. Informasi yang sangat akurat tetapi biayanya melebihi manfaat keputusan yang diambil, tidak bernilai.</p>
<p>➕ <strong>Sumber informasi</strong> bisa <strong>internal</strong> (data penjualan sendiri) dan <strong>eksternal</strong> (data pesaing, kebijakan pemerintah). Semakin tinggi level manajemen, semakin banyak informasi eksternal yang dibutuhkan (dibahas lagi di P5).</p>`, "Pengayaan")
  ],

  p3: [
    A("Mengapa Sistem Informasi Penting?", `<p>Setelah memahami <strong>sistem</strong> (P1) dan <strong>informasi</strong> (P2), sekarang keduanya digabung. Saat ini SI sudah menyatu dengan hampir semua fungsi bisnis: <strong>akuntansi, keuangan, manajemen operasi, pemasaran, manajemen SDM</strong>. Banyak ahli menyebut SI dan TI sebagai <strong>komponen vital</strong>, bahkan <strong>keharusan</strong>, bagi keberhasilan bisnis.</p>
<p>Contoh di sekitar kita: kampus PJJ tidak mungkin berjalan tanpa LMS dan SIAKAD; minimarket tidak bisa mengelola ribuan barang tanpa aplikasi kasir dan stok; bank tidak bisa melayani transfer real-time tanpa sistem core banking.</p>`, "Bagian 1 • Pengantar"),
    A("Definisi Sistem Informasi", `<p>Modul memberi tiga rumusan yang saling melengkapi:</p>
<ol><li>SI adalah kumpulan banyak <strong>komponen yang saling terkait</strong> dengan fungsi berbeda: <strong>input</strong>, <strong>processing</strong>, dan <strong>output</strong> berupa data atau informasi.</li><li>SI adalah komponen saling berkaitan yang berfungsi <strong>mengumpulkan, memproses, menyimpan, dan mendistribusikan informasi</strong> untuk mencapai tujuan tertentu. (Rumusan ini mirip definisi Laudon & Laudon.)</li><li>SI adalah <strong>semua sumber daya</strong> yang diperlukan untuk menyampaikan informasi dan mewujudkan <strong>tujuan organisasi</strong>.</li></ol>
<p>Benang merahnya: SI <strong>selalu punya tujuan</strong>. Karena itu, opsi “SI tidak bertujuan untuk mewujudkan organisasi” selalu salah.</p>`, "Bagian 2"),
    A("➕ SI Bukan Sekadar Komputer", `<p>Kesalahan umum mahasiswa baru adalah menyamakan SI dengan komputer atau aplikasi. Padahal:</p>
<ul><li><strong>Teknologi Informasi (TI)</strong> adalah <strong>alatnya</strong>: hardware, software, jaringan.</li><li><strong>Sistem Informasi (SI)</strong> adalah <strong>keseluruhan sistemnya</strong>: manusia, prosedur, data, dan TI yang bekerja bersama untuk tujuan organisasi.</li></ul>
<p>Analogi: TI adalah <strong>palu, gergaji, dan paku</strong>; SI adalah <strong>rumah</strong> yang dibangun tukang dengan rancangan tertentu. SI bahkan bisa berjalan secara <strong>manual</strong>, misalnya buku kas warung. O’Brien menyebut lima sumber daya SI: <strong>people, hardware, software, data, network</strong>. Lima sumber daya ini muncul lagi sebagai elemen CBIS di P5.</p>`, "Pengayaan"),
    A("Kerangka Kerja Konseptual SI (O’Brien)", `<p>O’Brien merangkum apa saja yang perlu dipahami seorang praktisi bisnis tentang SI dalam lima area (Gambar 3.1). Anggap ini sebagai “peta kurikulum” Sistem Informasi:</p>
<ol><li><strong>Foundation Concepts (konsep dasar)</strong>: dasar-dasar <strong>perilaku</strong> (bagaimana manusia memakai SI), permasalahan <strong>teknis</strong>, <strong>bisnis</strong>, dan konsep <strong>manajemen</strong>. Materi P1–P3 kita termasuk di sini.</li><li><strong>Information Technologies</strong>: konsep, pengembangan, dan isu manajemen <strong>hardware, software, manajemen data</strong>, serta teknologi berbasis <strong>internet/jaringan</strong>. Ini materi P6–P7, dan mata kuliah Basis Data.</li><li><strong>Business Applications</strong>: penggunaan SI untuk <strong>operasional, manajemen</strong>, industri, dan <strong>pengambilan keputusan</strong>. Ini materi P4–P5.</li><li><strong>Development Processes</strong>: proses <strong>pengembangan dan implementasi</strong> SI untuk memanfaatkan peluang bisnis. Kelak dipelajari di Analisis & Perancangan SI.</li><li><strong>Management Challenges</strong>: <strong>pengelolaan</strong> SI dan tantangannya: keamanan, etika, pengendalian, pengelolaan TI global.</li></ol>
<p>Jembatan keledai: <strong>F-I-B-D-M</strong> → “Fondasi, IT, Bisnis, Develop, Manage”.</p>`, "Bagian 3"),
    A("Proses Kerja SI: Input, Processing, Output", `<p>Gambar 3.2 menunjukkan alur kerja SI:</p>
<ul><li><strong>Input</strong>: mengumpulkan dan <strong>menangkap (capturing) data mentah</strong>, misalnya scan barcode, isi formulir online.</li><li><strong>Processing</strong>: <strong>transformasi data</strong> menjadi sesuatu yang lebih berguna, melibatkan <strong>kalkulasi, perbandingan data, dan pencarian alternatif</strong>.</li><li><strong>Output</strong>: hasil pengolahan berupa informasi yang <strong>sesuai tujuan SI</strong>, misalnya laporan, notifikasi, dashboard.</li></ul>
<p>➕ Model lengkap O’Brien menambahkan dua aktivitas: <strong>storage</strong> (menyimpan data agar bisa dipakai lagi, misalnya di database) dan <strong>control of system performance</strong> (memantau dan memberi umpan balik). Perhatikan bahwa ini persis karakteristik sistem di P1: input, processing, output, control, feedback.</p>`, "Bagian 4"),
    A("Tiga Peran Fundamental SI", `<p>Gambar 3.3 berbentuk <strong>segitiga</strong> yang menunjukkan tiga peran SI dalam organisasi, dari dasar ke puncak:</p>
<ol><li><strong>Support business processes and operations</strong> (dasar segitiga): SI mendukung operasi harian. Contoh modul: retail memakai SI untuk mencatat pembelian pelanggan, persediaan bahan baku, pembayaran pegawai, dan evaluasi tren penjualan. Tanpa peran ini, organisasi bahkan tidak bisa berjalan.</li><li><strong>Support business decision making</strong> (tengah): SI membantu manajer mengambil keputusan yang lebih baik. Contoh modul: perusahaan pangan menghitung kebutuhan pasokan harian dengan SI sehingga terhindar dari <em>human error</em>.</li><li><strong>Support strategies for competitive advantage</strong> (puncak): SI dipakai sebagai senjata strategis agar unggul dari pesaing. Contoh modul: e-commerce mengubah strategi pemasaran sehingga produk tetap laku dan tidak kalah saing.</li></ol>
<p>Kenapa bentuknya segitiga? Karena semakin ke atas, perannya semakin <strong>strategis</strong> tetapi <strong>bergantung</strong> pada peran di bawahnya. Keputusan yang baik butuh data operasional yang rapi; strategi bersaing butuh keputusan yang baik.</p>`, "Bagian 5"),
    tip("Awas nama peran yang ditukar", "Pasangannya harus tepat: <strong>strategies</strong> → for competitive advantage; <strong>business</strong> → decision making; <strong>business</strong> → processes and operations. Opsi seperti “support <em>business</em> for competitive advantage” atau “support business local” adalah pengecoh.", "warn"),
    A("➕ Pengayaan: Contoh Tiga Peran pada Satu Perusahaan", `<p>Ambil contoh <strong>jaringan kedai kopi</strong>:</p>
<ul><li><strong>Proses & operasi</strong>: aplikasi kasir mencatat setiap pesanan, stok biji kopi berkurang otomatis.</li><li><strong>Pengambilan keputusan</strong>: dashboard menunjukkan menu yang kurang laku sehingga manajer memutuskan menggantinya; data jam ramai dipakai menyusun jadwal barista.</li><li><strong>Keunggulan kompetitif</strong>: aplikasi member dengan poin dan pesan-antar membuat pelanggan setia, sesuatu yang sulit ditiru kedai kecil.</li></ul>
<p>➕ Dalam literatur lain (Laudon), tujuan strategis SI dirumuskan sebagai: <em>operational excellence, produk/layanan baru, kedekatan dengan pelanggan & pemasok, pengambilan keputusan yang lebih baik, keunggulan kompetitif, dan bertahan hidup (survival)</em>.</p>`, "Pengayaan")
  ],

  p4: [
    A("Mengapa Ada Banyak Tipe SI?", `<p>Organisasi memiliki banyak kebutuhan berbeda: kasir butuh mencatat transaksi dengan cepat, manajer butuh laporan bulanan, direktur butuh gambaran besar untuk strategi. Satu sistem tidak bisa melayani semuanya dengan baik, sehingga muncul berbagai <strong>tipe SI</strong>.</p>
<p>Modul (mengikuti O’Brien) membagi SI menjadi dua kelompok besar: <strong>Operation Support Systems</strong> (mendukung operasi harian) dan <strong>Management Support Systems</strong> (mendukung manajer dalam membuat laporan dan keputusan).</p>`, "Bagian 1 • Pengantar"),
    A("Operation Support Systems (OSS)", `<p>OSS adalah sistem yang mendukung <strong>operasi harian</strong> organisasi. Modul menyebutnya juga “sistem pendukung transaksi”. Ciri utamanya: menghasilkan banyak data dan informasi untuk keperluan <strong>internal dan eksternal</strong>, tetapi biasanya <strong>tidak langsung</strong> menghasilkan informasi khusus untuk manajer. Jenisnya menurut modul:</p>
<ul><li><strong>Transaction Processing System (TPS)</strong>: memproses data transaksi <strong>dalam jumlah besar</strong>; mengolah, mengedit, dan meng-update <strong>database operasional</strong>. Contoh: penggajian, inventaris, mesin kasir (POS), sistem reservasi tiket, KRS online. ➕ TPS bisa bekerja secara <strong>batch</strong> (dikumpulkan lalu diproses sekaligus, misalnya penggajian akhir bulan) atau <strong>real-time/online</strong> (langsung diproses, misalnya transfer bank).</li><li><strong>Process Control System (PCS)</strong>: <strong>memantau dan mengendalikan</strong> proses fisik/produksi. Contoh: sensor suhu di pabrik semen, pengendalian mesin pengisian botol, sistem di kilang minyak.</li><li><strong>Enterprise Collaboration System (ECS)</strong>: mendukung <strong>kerja sama, komunikasi, dan koordinasi tim</strong>. Contoh: email, konferensi video (Zoom/Meet), Google Drive bersama, grup chat kantor.</li><li><strong>Expert System (sistem pakar)</strong>: memuat <strong>kepakaran/pengetahuan ahli</strong> dan memberi <strong>saran</strong> kepada pengguna. Contoh modul: sistem pakar pengobatan ternak domba. Contoh lain: diagnosis kerusakan motor, deteksi penyakit tanaman.</li></ul>`, "Bagian 2"),
    tip("Posisi expert system", "Di buku O’Brien, OSS hanya berisi <strong>TPS, PCS, ECS</strong>. Expert system dimasukkan ke kategori lain (“<em>other categories</em>”) bersama <em>knowledge management systems</em>, <em>strategic information systems</em>, dan <em>functional business systems</em>. Untuk CPMK, ikuti modul; untuk wawasan, ketahui versi aslinya.", "warn"),
    A("Management Support Systems (MSS)", `<p>MSS adalah sistem yang membantu manajer <strong>mengelola informasi</strong> untuk <strong>membuat laporan</strong> dan <strong>mengambil keputusan</strong>. Jenisnya tiga:</p>
<ul><li><strong>Management Information System (MIS)</strong>: menyajikan informasi dalam <strong>format laporan yang sudah ditentukan</strong>, biasanya rutin (harian, mingguan, bulanan). Contoh modul: petinggi perusahaan melacak laporan barang keluar-masuk dan mengevaluasi transaksi. ➕ Jenis laporannya: <em>periodic</em> (terjadwal), <em>exception</em> (hanya saat ada penyimpangan, misalnya stok di bawah minimum), dan <em>demand</em> (diminta sewaktu-waktu).</li><li><strong>Decision Support System (DSS)</strong>: membantu manajer mengambil keputusan dan memberi <strong>rekomendasi</strong>, terutama untuk masalah <strong>semi-terstruktur</strong>. Contoh modul: memprediksi penjualan produk baru. ➕ Ciri khasnya analisis <strong>what-if</strong> (“jika harga naik 10%, berapa laba?”) dan <strong>sensitivitas</strong>.</li><li><strong>Executive Information System (EIS)</strong>: untuk kebutuhan <strong>eksekutif/C-level</strong> (CEO, CFO, direktur). Menyajikan informasi ringkas dalam bentuk <strong>grafik</strong>, fokus pada area kerja utama (<em>critical success factors</em>), dan mendukung pengendalian yang efisien waktu. ➕ Biasanya bisa <em>drill-down</em>: klik angka ringkas untuk melihat rinciannya.</li></ul>`, "Bagian 3"),
    A("Cara Membedakan MIS, DSS, dan EIS", `<p>Ketiganya sama-sama untuk manajemen, sehingga sering tertukar. Pakai tiga pertanyaan:</p>
<ol><li><strong>Bentuk keluarannya laporan berformat tetap?</strong> → MIS.</li><li><strong>Membantu memilih alternatif/memberi rekomendasi, ada simulasi?</strong> → DSS.</li><li><strong>Penggunanya eksekutif puncak, tampilannya ringkas dan grafis?</strong> → EIS.</li></ol>
<p>Contoh di rumah sakit: laporan jumlah pasien per bulan untuk kepala bagian (MIS); analisis apakah perlu membuka poli baru (DSS); dashboard kinerja RS untuk direktur (EIS).</p>`, "Bagian 4"),
    A("➕ Pengayaan: Tipe SI dan Tingkat Manajemen", `<p>Tipe SI biasanya dipetakan ke <strong>piramida organisasi</strong>:</p>
<ul><li><strong>Manajemen puncak (strategis)</strong>: keputusan jangka panjang dan tidak terstruktur → <strong>EIS, DSS</strong>.</li><li><strong>Manajemen menengah (taktis)</strong>: pengendalian dan laporan periodik → <strong>MIS, DSS</strong>.</li><li><strong>Operasional</strong>: kegiatan harian yang terstruktur → <strong>TPS, PCS</strong>.</li><li><strong>Pekerja pengetahuan & staf kantor</strong>: <strong>ECS</strong>, sistem otomasi kantor, <strong>KMS</strong> (Knowledge Management System).</li></ul>
<p>Pola ini akan muncul lagi di P5 sebagai <strong>level CBIS</strong> (operational control → management control → strategic planning).</p>
<p>➕ Tipe lain yang sering disebut di buku modern: <strong>ERP</strong> (Enterprise Resource Planning, menyatukan semua fungsi bisnis), <strong>CRM</strong> (Customer Relationship Management), <strong>SCM</strong> (Supply Chain Management), dan <strong>Business Intelligence</strong>.</p>`, "Pengayaan"),
    tip("Persiapan CPMK 1", "CPMK 1 mencakup <strong>P1–P4</strong>. Setelah membaca materi ini, buka <strong>Visual Cheat Sheet</strong> untuk peta materi P1–P4 dan daftar pengecoh, lalu kerjakan <strong>bank soal di tab Kuis</strong>. Baca pembahasan setiap soal yang salah.")
  ],

  p5: [
    A("Dari SI ke CBIS", `<p>SI bisa saja manual, tetapi hampir semua SI modern berjalan di atas komputer. SI yang memanfaatkan komputer disebut <strong>Computer Based Information System (CBIS)</strong>.</p>
<p>Gambar 5.1 di modul menggambarkan alur berpikirnya: kita mulai dari memahami <strong>manajemen dan organisasi</strong>, lalu <strong>konsep sistem</strong> (P1) dan <strong>konsep informasi</strong> (P2) membentuk <strong>konsep SI</strong> (P3). Konsep SI dipadukan dengan <strong>konsep TI</strong> (P6), dan hasil perpaduannya adalah <strong>CBIS</strong>.</p>`, "Bagian 1 • Pengantar"),
    A("Pengertian CBIS", `<p><strong>Leonard Jessup</strong>: CBIS adalah kombinasi <strong>hardware, software, dan jaringan telekomunikasi</strong> yang sengaja dibangun untuk <strong>mengumpulkan (collect), membuat (create), dan mendistribusikan (distribute)</strong> data yang berguna dalam organisasi.</p>
<p>Rumusan kedua di modul: CBIS adalah sistem yang <strong>mengolah data menjadi informasi berkualitas</strong> yang dimanfaatkan sebagai alat bantu <strong>pengambilan keputusan, koordinasi, kendali</strong>, hingga <strong>visualisasi dan analisis</strong>.</p>
<p>Contoh CBIS yang kamu pakai: LMS kampus, m-banking, aplikasi marketplace, SIAKAD.</p>`, "Bagian 2"),
    A("Lima Elemen CBIS", `<ol><li><strong>Data/Database</strong>: kumpulan file atau data dan informasi yang disimpan di media penyimpanan (harddisk, magnetic tape, ➕ SSD, cloud) agar mudah diakses pengguna.</li><li><strong>People (manusia)</strong>: programmer, system analyst, operator, data entry, manajer; semuanya bertanggung jawab atas <strong>perawatan sistem</strong>. ➕ Juga <strong>end user</strong>, yaitu orang yang memakai hasil sistem (pelanggan, mahasiswa).</li><li><strong>Telecommunication</strong>: komunikasi yang menghubungkan pengguna dengan sistem komputer dalam <strong>jaringan kerja yang efektif dan efisien</strong>. Contoh: LAN kantor, internet, Wi-Fi, jaringan seluler.</li><li><strong>Hardware</strong>: komponen untuk kegiatan <strong>masukan, pemrosesan, dan keluaran</strong> data.</li><li><strong>Software</strong>: program/instruksi untuk komputer. Modul membaginya menjadi sistem perangkat lunak umum, sistem manajemen data, dan sistem pengoperasian. ➕ Pembagian yang lebih umum: <strong>system software</strong> dan <strong>application software</strong> (dibahas di P6).</li></ol>
<p>➕ Beberapa buku (Stair & Reynolds) menambahkan elemen keenam: <strong>procedures</strong>, yaitu aturan dan SOP penggunaan sistem. Contoh: prosedur backup harian, prosedur reset password.</p>`, "Bagian 3"),
    A("Empat Fungsi CBIS (Area Fungsional)", `<p>CBIS dipakai di berbagai bagian perusahaan. Modul menyebut empat:</p>
<ul><li><strong>Human Resource Information System (HRIS)</strong>: mengelola tata kelola SDM: rekrutmen, data pegawai, absensi, penggajian, penilaian kinerja, pelatihan. Informasinya mendukung keputusan kepegawaian.</li><li><strong>Finance Information System</strong>: memberi informasi <strong>keuangan</strong> kepada orang di dalam maupun luar perusahaan, termasuk <strong>arus uang</strong> bagi pemakai di seluruh perusahaan. Contoh: laporan arus kas, anggaran, laporan laba-rugi.</li><li><strong>Manufacturing Information System</strong>: terhubung dengan SI lain untuk <strong>memecahkan masalah produksi</strong>: perencanaan produksi, kebutuhan bahan baku, pengendalian mutu, jadwal mesin.</li><li><strong>Marketing Information System</strong>: menganalisis dan menilai informasi <strong>pemasaran</strong> yang dikumpulkan <strong>terus-menerus</strong> dari sumber <strong>di dalam dan di luar</strong> organisasi; menjadi alat bantu operasional, manajerial, dan strategis. Contoh: analisis tren pembeli, harga pesaing, efektivitas iklan.</li></ul>
<p>Pengecoh di soal: “Restore Information System” tidak ada.</p>`, "Bagian 4"),
    A("Level CBIS", `<p>CBIS juga dibedakan menurut <strong>tingkat manajemen</strong> yang dilayaninya:</p>
<ul><li><strong>Strategic planning</strong> (puncak): keputusan jangka panjang (membuka cabang baru, produk baru) → <strong>EIS / DSS</strong>.</li><li><strong>Management control</strong> (tengah): memantau dan mengendalikan kinerja bagian → <strong>MIS</strong>.</li><li><strong>Operational control</strong> (bawah): memastikan tugas harian berjalan → <strong>TPS</strong>.</li></ul>
<p>➕ Karakter informasinya berbeda di tiap level. Di level operasional: <strong>rinci</strong>, sering (harian), sebagian besar <strong>internal</strong>. Di level strategis: <strong>ringkas</strong>, jangka panjang, banyak memakai data <strong>eksternal</strong> (kondisi ekonomi, pesaing). Perhatikan bahwa ini sama dengan piramida tipe SI di P4.</p>`, "Bagian 5"),
    A("Model CBIS (McLeod)", `<p>Model CBIS menjelaskan bagaimana sistem membantu menyelesaikan masalah, dari masalah muncul sampai solusi ditemukan:</p>
<ol><li><strong>Problems</strong>: organisasi menghadapi masalah (misalnya penjualan turun).</li><li>Masalah masuk ke <strong>CBIS</strong>, yang terdiri dari subsistem: <strong>TPS</strong> (menyediakan data transaksi), <strong>MIS</strong>, <strong>DSS</strong>, <strong>Virtual Office</strong>, dan <strong>Knowledge-based System</strong>.</li><li>Subsistem-subsistem itu menghasilkan <strong>information</strong>.</li><li>Informasi dipakai untuk mengambil <strong>decision</strong>.</li><li>Keputusan menghasilkan <strong>problem solution</strong>.</li></ol>
<p>➕ <strong>Virtual office</strong> (otomasi perkantoran) adalah pemanfaatan teknologi agar pekerjaan kantor tidak terikat tempat: email, konferensi video, dokumen bersama, telecommuting. <strong>Knowledge-based system</strong> adalah sistem yang memakai basis pengetahuan untuk memberi saran, termasuk <strong>sistem pakar</strong> dan ➕ kini sistem berbasis <strong>AI</strong>.</p>`, "Bagian 6"),
    tip("Contoh utuh", "Masalah: “stok sering habis”. <strong>TPS</strong> mencatat penjualan harian → <strong>MIS</strong> membuat laporan barang yang paling sering habis → <strong>DSS</strong> menghitung titik pemesanan ulang yang optimal → manajer <strong>memutuskan</strong> mengubah jadwal pemesanan → <strong>solusi</strong>: stok aman. Tim berkoordinasi lewat <strong>virtual office</strong> (rapat online, dokumen bersama).")
  ],

  p6: [
    A("Apa Itu Teknologi Informasi?", `<p><strong>Larry & Nancy Long</strong>: TI adalah <strong>gabungan (integrasi) teknologi komputer</strong> (<em>computing technology</em>) dengan <strong>pengolahan informasi</strong> (<em>information processing</em>).</p>
<p><strong>Beynon-Davies</strong>: TI terdiri dari <strong>artefak</strong>, yaitu barang buatan atau hasil penemuan manusia, yang digunakan untuk <strong>pengumpulan, penyimpanan, penyebaran, dan manipulasi data</strong>.</p>
<p>Ingat kembali perbedaannya dengan SI (P3): TI adalah <strong>alat</strong>, SI adalah <strong>sistem</strong> yang memakai alat itu bersama manusia dan prosedur.</p>
<p><strong>Modern Information Technology</strong> terdiri dari: <strong>perangkat keras</strong> (aspek fisik/<em>hard</em> dari TI), <strong>perangkat lunak</strong> (aspek non-fisik/<em>soft</em>), <strong>teknologi komunikasi</strong> (berbagai bentuk interkoneksi antar komponen TI), dan <strong>data</strong>. Komponen-komponen ini tersusun menjadi <strong>IT System</strong>.</p>`, "Bagian 1"),
    A("Akar Sejarah: Mesin Turing", `<p>Perangkat keras komputer dikembangkan berdasarkan model komputasi yang disebut <strong>Mesin Turing</strong>, yaitu <strong>model ideal untuk melakukan penghitungan matematis</strong>. Mesin Turing bukan mesin fisik, melainkan model teoretis: pita panjang berisi simbol, kepala baca-tulis, dan aturan langkah demi langkah. Model sederhana ini terbukti mampu menggambarkan <strong>semua hal yang bisa dihitung komputer</strong>.</p>
<p>➕ Koreksi: Alan Turing memperkenalkannya dalam makalah <em>On Computable Numbers</em> tahun <strong>1936</strong> (modul menulis 1930). Alonzo Church bekerja <strong>terpisah</strong> dengan <em>lambda calculus</em> yang terbukti setara; gabungan gagasan keduanya dikenal sebagai <strong>tesis Church–Turing</strong>.</p>
<p>Selanjutnya, perkembangan hardware sangat bergantung pada kemajuan <strong>rekayasa elektronika</strong>. Setiap lompatan komponen elektronik melahirkan satu <strong>generasi</strong> komputer.</p>`, "Bagian 2"),
    A("Empat Generasi Komputer", `<ul><li><strong>Generasi 1: tabung hampa (vacuum tubes).</strong> Modul menyebut dekade 30-an–40-an (➕ banyak buku: ±1940–1956). Ukuran sangat besar, lambat, boros listrik, panas, dan sering gagal. Contoh <strong>ENIAC</strong>: ±18.000 tabung, gagal setiap ±7 menit, beratnya sekitar 30 ton dan memenuhi satu ruangan.</li><li><strong>Generasi 2: transistor.</strong> Dekade 50-an – pertengahan 60-an. Transistor menggantikan tabung, sehingga komputer <strong>lebih kecil</strong>, <strong>1000 kali lebih cepat</strong>, lebih <strong>andal</strong>, dan lebih <strong>murah</strong>. ➕ Mulai dipakai bahasa pemrograman tingkat tinggi seperti FORTRAN dan COBOL.</li><li><strong>Generasi 3: Integrated Circuit (IC).</strong> Akhir 60-an – 70-an. Ratusan transistor dikemas dalam satu <strong>silicon chip</strong>. Ukuran dan biaya turun drastis; reliability, speed, dan efficiency naik signifikan. Produksi chip massal membuat harganya sangat murah. ➕ Mulai dikenal sistem operasi yang menjalankan banyak program sekaligus.</li><li><strong>Generasi 4: mikroprosesor.</strong> 70-an – sekarang. Ribuan hingga miliaran transistor dalam satu chip prosesor. Perubahan radikal pada ukuran, kemampuan, kecepatan, dan harga, sehingga lahir <strong>komputer pribadi (PC)</strong>, laptop, dan smartphone.</li></ul>
<p>➕ Banyak buku menambahkan <strong>generasi 5</strong>: komputer berbasis <strong>kecerdasan buatan (AI)</strong>, pemrosesan paralel, dan pengenalan bahasa alami.</p>`, "Bagian 3"),
    A("Jenis Komputer Menurut Ukuran", `<p>Berdasarkan <strong>ukuran, kemampuan, dan jumlah pengguna</strong>, modul membagi hardware menjadi:</p>
<ul><li><strong>Mainframe</strong>: terbesar, <strong>multi-user</strong>, untuk pengolahan data skala besar. Contoh penggunaan: core banking, sistem reservasi maskapai.</li><li><strong>Minicomputer</strong> (disebut juga <strong>midrange computer</strong>): ukuran dan kemampuan menengah, untuk perusahaan menengah atau departemen.</li><li><strong>Microcomputer</strong> (<strong>personal computer/PC</strong>): untuk satu pengguna; termasuk desktop dan laptop.</li></ul>
<p>➕ Di atas mainframe ada <strong>supercomputer</strong> (riset cuaca, simulasi ilmiah). Saat ini peran mini/midrange banyak digantikan <strong>server</strong> dan layanan <strong>cloud</strong>.</p>`, "Bagian 4"),
    A("Perangkat Keras (Hardware)", `<p>Perangkat komputer terdiri dari tiga bagian: <strong>hardware</strong>, <strong>software</strong>, dan <strong>brainware</strong> (manusia yang mengoperasikan: pengguna, programmer, operator, analis).</p>
<p><strong>Hardware</strong> adalah alat komputer yang <strong>dapat dilihat, disentuh, dan berwujud</strong>. Biasanya dirakit dalam casing dan dibedakan menurut fungsinya. Contoh di modul:</p>
<ul><li><strong>Keyboard</strong> (input): jenis USB, wireless, PS/2.</li><li><strong>Mouse</strong> (input): banyak dipakai di sistem operasi grafis.</li><li><strong>Scanner</strong> (input): memasukkan data <strong>gambar</strong>; prinsipnya mirip <strong>mesin fotokopi</strong>.</li><li><strong>Mic</strong> (input): memasukkan data suara/audio.</li><li><strong>CPU</strong> (proses): <strong>otak komputer</strong>; memproses kalkulasi dan perintah. Dilengkapi kipas karena panas. CPU baru sudah memiliki <strong>GPU terintegrasi</strong> untuk mengolah grafis.</li><li><strong>Motherboard</strong>: papan dengan slot-slot yang <strong>menghubungkan seluruh komponen</strong> PC.</li><li><strong>RAM (Random Access Memory)</strong>: tempat transit data <strong>sementara</strong> untuk operasi CPU. Bersifat <strong>volatile</strong>: isinya hilang saat listrik mati.</li></ul>
<p>➕ Yang belum disebut modul: <strong>alat output</strong> (monitor, printer, speaker, proyektor), <strong>media penyimpanan</strong> (HDD, SSD, flashdisk, kartu memori), dan <strong>ROM</strong> (memori <em>non-volatile</em> berisi instruksi awal/BIOS). Kapasitas RAM di modul (256 MB–16 GB) sudah lama; saat ini PC/laptop umumnya 8–32 GB.</p>`, "Bagian 5"),
    A("Perangkat Lunak (Software)", `<p>Software adalah bagian sistem komputer yang <strong>tidak berwujud fisik</strong>: kumpulan data elektronik berupa <strong>program</strong> yang dijalankan untuk menyelesaikan perintah. Dua kategorinya:</p>
<ul><li><strong>Perangkat lunak sistem (system software)</strong>: berfungsi sebagai <strong>pengendali dan koordinasi</strong> kegiatan sistem komputer. ➕ Contoh: <strong>sistem operasi</strong> (Windows, Linux, macOS, Android), <strong>driver</strong> (penghubung OS dengan hardware), <strong>utility</strong> (antivirus, disk cleanup, kompresi file).</li><li><strong>Perangkat lunak aplikasi (application software)</strong>: dibuat dengan bahasa pemrograman tertentu untuk menyelesaikan <strong>tugas khusus pengguna</strong>. ➕ Contoh: Microsoft Word, browser, aplikasi kasir, game, m-banking, aplikasi ojek online.</li></ul>
<p>Analogi: system software adalah <strong>manajer gedung</strong> yang mengatur listrik, lift, dan ruangan; application software adalah <strong>penyewa</strong> yang memakai ruangan untuk usahanya masing-masing.</p>
<p>➕ Bahasa pemrograman sendiri juga software. Kode yang ditulis programmer diterjemahkan ke bahasa mesin oleh <strong>compiler</strong> atau <strong>interpreter</strong>.</p>`, "Bagian 6"),
    tip("Hubungan dengan materi lain", "Hardware, software, dan jaringan di P6 adalah <strong>elemen CBIS</strong> (P5) dan termasuk kerangka <strong>Information Technologies</strong> O’Brien (P3). Brainware = elemen <strong>people</strong> di CBIS.")
  ],

  p7: [
    A("Kenapa Data Perlu Dikelola?", `<p>Informasi yang baik (P2) hanya bisa dihasilkan dari data yang <strong>rapi, konsisten, dan aman</strong>. Pertemuan ini membahas bagaimana data disusun di komputer, masalah yang muncul bila data dikelola dengan cara lama, dan siapa saja orang yang bertugas mengelolanya.</p>`, "Bagian 1 • Pengantar"),
    A("Hierarki Data (File Organization Concept)", `<p>Data di komputer tersusun bertingkat dari yang paling kecil:</p>
<ol><li>➕ <strong>Bit</strong> (0/1) → <strong>byte</strong> (8 bit) yang mewakili satu <strong>karakter</strong> (huruf, angka, simbol).</li><li><strong>Field</strong>: kumpulan karakter yang punya arti, misalnya NIM “2024310045” atau nama “Gilang”.</li><li><strong>Record</strong>: kumpulan field yang <strong>menggambarkan satu entity</strong>, misalnya satu baris data mahasiswa (NIM, nama, prodi, angkatan).</li><li><strong>File</strong>: kumpulan record yang <strong>sejenis</strong> (<em>group of records of same type</em>), misalnya file seluruh mahasiswa.</li><li><strong>Database</strong>: kumpulan file yang <strong>saling terkait</strong> (<em>group of related files</em>), misalnya file mahasiswa + file mata kuliah + file nilai.</li></ol>
<p>Dua istilah penting lagi:</p>
<ul><li><strong>Entity</strong>: orang, tempat, atau benda (<em>person, place, thing</em>) yang informasinya disimpan. Contoh: mahasiswa, dosen, ruang, mata kuliah (COURSE).</li><li><strong>Attribute</strong>: setiap karakteristik atau kualitas yang menggambarkan entity. Contoh modul: <em>Date</em> dan <em>Grade</em> adalah atribut dari entity COURSE.</li></ul>
<p>Hubungannya: <strong>satu record = satu entity</strong>, <strong>satu field = satu attribute</strong>. Dalam tabel database, record adalah <strong>baris</strong> dan field adalah <strong>kolom</strong> (dipelajari lebih dalam di mata kuliah Basis Data).</p>`, "Bagian 2"),
    A("Masalah Pemrosesan File Tradisional", `<p>Dulu, setiap departemen membuat dan mengelola <strong>file sendiri-sendiri</strong>. Bagian akademik punya file mahasiswa, bagian keuangan punya file mahasiswa sendiri, perpustakaan juga. Cara ini memunculkan masalah:</p>
<ul><li><strong>Data redundancy</strong>: data yang sama <strong>disimpan berulang</strong> di banyak tempat. Alamat mahasiswa tersimpan di tiga file departemen. Akibatnya boros ruang dan sulit diperbarui. (➕ Modul menulis “duplikasi dalam satu field yang sama”; pengertian yang lebih tepat adalah duplikasi di banyak file/tempat.)</li><li><strong>Data inconsistency</strong>: atribut sama tetapi <strong>nilainya berbeda</strong>. Mahasiswa pindah rumah dan hanya melapor ke akademik, sehingga alamat di keuangan masih yang lama. Inconsistency adalah <strong>akibat</strong> dari redundancy.</li><li><strong>Program-data dependence</strong>: program dan data saling terikat erat; <strong>perubahan pada program membutuhkan perubahan pada data</strong> yang diakses (dan sebaliknya). Menambah satu kolom email bisa memaksa semua program yang membaca file itu ditulis ulang.</li><li><strong>Lack of flexibility</strong>: sulit memenuhi permintaan laporan baru atau mendadak, karena harus membuat program baru.</li><li><strong>Poor security</strong>: sulit mengatur siapa boleh melihat dan mengubah data karena file tersebar.</li><li><strong>Lack of data sharing and availability</strong>: data sulit dibagi antar departemen, sehingga tidak tersedia saat dibutuhkan bagian lain.</li></ul>`, "Bagian 3"),
    A("➕ Solusinya: Pendekatan Database dan DBMS", `<p>Masalah-masalah di atas diatasi dengan <strong>pendekatan database</strong>: data organisasi disimpan <strong>terpusat</strong> dan dikelola oleh perangkat lunak khusus bernama <strong>DBMS (Database Management System)</strong>, misalnya MySQL, PostgreSQL, Oracle, SQL Server.</p>
<ul><li>Redundansi <strong>berkurang</strong> karena satu data cukup disimpan sekali.</li><li>Data <strong>konsisten</strong> karena perubahan dilakukan di satu tempat.</li><li><strong>Program-data independence</strong>: struktur data bisa diubah tanpa menulis ulang semua program.</li><li><strong>Keamanan</strong> diatur terpusat dengan hak akses per pengguna.</li><li>Data bisa <strong>dibagi</strong> ke semua bagian dan laporan baru mudah dibuat dengan bahasa query (SQL).</li></ul>`, "Pengayaan"),
    A("Information Specialist", `<p>Pengelolaan data dan informasi membutuhkan orang-orang dengan peran khusus:</p>
<ul><li><strong>System analyst (analis sistem)</strong>: ahli <strong>menjabarkan permasalahan</strong> perusahaan yang berkaitan dengan sistem komputer. ➕ Ia menjadi “penerjemah” antara kebutuhan pengguna bisnis dan tim teknis: mewawancarai pengguna, merumuskan kebutuhan, merancang solusi.</li><li><strong>Database administrator (DBA)</strong>: bertanggung jawab atas <strong>implementasi, perencanaan, operasi, dan keamanan</strong> data. ➕ Tugas nyata: mengatur hak akses, backup & recovery, memantau kinerja database.</li><li><strong>Operator</strong>: menjalankan komputer skala besar seperti <strong>server atau mainframe</strong> di pusat komputasi, serta <strong>memonitor penggunaan hardware</strong>.</li><li><strong>Network specialist</strong>: memastikan <strong>jaringan</strong> perusahaan sesuai prosedur; <strong>bekerja sama dengan system analyst</strong> untuk menyatukan sumber daya komputasi.</li></ul>
<p>➕ Peran lain yang umum: <strong>programmer</strong> (menulis program dari rancangan analis), <strong>webmaster</strong>, <strong>data analyst/data scientist</strong>, <strong>IT security specialist</strong>, dan <strong>CIO (Chief Information Officer)</strong> yang memimpin seluruh fungsi SI di organisasi. Sebagai lulusan SI, kamu bisa menempati banyak peran ini, terutama system analyst dan data analyst.</p>`, "Bagian 4"),
    tip("Hubungan dengan P2", "Data inconsistency langsung merusak karakteristik informasi <strong>accurate</strong> dan <strong>reliable</strong>; poor security merusak <strong>secure</strong>; lack of sharing merusak <strong>accessible</strong> dan <strong>timely</strong>. Hubungan lintas materi seperti ini cocok untuk soal UTS.")
  ],

  p8: [
    A("Cara Memakai Halaman UTS Ini", `<p>UTS (CPMK 2) mengambil soal dari <strong>P1–P7</strong>. Urutan belajar yang disarankan:</p>
<ol><li>Baca ulang <strong>Materi Lengkap</strong> P1–P7 (cukup bagian yang belum kamu kuasai).</li><li>Buka <strong>Visual Cheat Sheet</strong> di halaman ini: peta materi dan daftar pengecoh.</li><li>Kerjakan <strong>Simulator</strong>: latihan “pertemuan berapa?” dan studi kasus gabungan.</li><li>Kerjakan <strong>bank soal</strong> di tab Kuis. Setiap pembahasan diberi label pertemuan, jadi kamu tahu materi mana yang perlu diulang.</li></ol>`, "Panduan"),
    A("Benang Merah P1–P7", `<p>Semua materi Dasar-dasar SI sebenarnya satu cerita yang bersambung:</p>
<ol><li><strong>P1 Sistem</strong>: segala sesuatu bisa dilihat sebagai elemen yang berinteraksi untuk tujuan, dengan input–proses–output, kendali, umpan balik, dan batas.</li><li><strong>P2 Informasi</strong>: tujuan sistem informasi adalah mengubah <strong>data</strong> menjadi <strong>informasi</strong> yang berkualitas (11 karakteristik), lalu menjadi <strong>pengetahuan</strong>.</li><li><strong>P3 Sistem Informasi</strong>: gabungan keduanya; SI mengumpulkan, memproses, menyimpan, mendistribusikan informasi, dengan tiga peran: operasi, keputusan, keunggulan bersaing.</li><li><strong>P4 Tipe SI</strong>: peran-peran itu diwujudkan dalam sistem nyata: TPS/PCS/ECS/ES untuk operasi; MIS/DSS/EIS untuk manajemen.</li><li><strong>P5 CBIS</strong>: SI yang dijalankan dengan komputer, dengan 5 elemen, 4 area fungsi, 3 level (yang sama dengan piramida P4), dan model pemecahan masalah.</li><li><strong>P6 TI</strong>: “alat” yang membuat CBIS mungkin: sejarah hardware, jenis komputer, hardware dan software.</li><li><strong>P7 Data</strong>: bahan baku semua itu adalah data, yang harus disusun (field→database) dan dikelola oleh orang yang tepat agar tidak redundant dan inconsistent.</li></ol>
<p>Jika kamu bisa menceritakan ulang alur ini dengan kata-katamu sendiri, kamu sudah siap untuk soal studi kasus.</p>`, "Rangkuman"),
    A("Pola Soal yang Perlu Diwaspadai", `<ul><li><strong>“…, kecuali”</strong>: hafalkan daftar lengkapnya (6 karakteristik, 5K, 11 karakteristik informasi, 5 kerangka, 3 peran, 4+3 tipe SI, 5 elemen & 4 fungsi CBIS, 5 masalah file, 4 information specialist). Opsi yang tidak ada di daftar adalah jawabannya.</li><li><strong>“…yang salah, kecuali”</strong>: artinya cari satu yang <strong>benar</strong>.</li><li><strong>Studi kasus</strong>: cari kata kerjanya. Mencatat transaksi → TPS; laporan format tetap → MIS; rekomendasi/prediksi → DSS; eksekutif/grafik → EIS; mengendalikan mesin → PCS; kolaborasi → ECS; meniru ahli → ES.</li><li><strong>Nama yang dipelesetkan</strong>: Resource Access Memory, Restore Information System, Teleconference, Support business local, Konsolidasi, Innovation. Semuanya pengecoh.</li><li><strong>Lintas materi</strong>: level CBIS = piramida tipe SI; elemen CBIS = sumber daya SI O’Brien; inconsistency merusak accurate.</li></ul>`, "Strategi")
  ]
};
// Sisipkan diagram & blok interaktif setelah artikel yang judulnya memuat teks tertentu
const after = (key, title, ...blocks) => { const arr = M[key]; const i = arr.findIndex(b => (b.title || "").includes(title)); if (i < 0) throw new Error("materi " + key + ": " + title); arr.splice(i + 1, 0, ...blocks); };
const rv = (label, title, items) => ({ type: "reveal", label, title, items });
after("p1", "Enam Karakteristik", D.modelSistem);
after("p1", "Umpan Balik Negatif", rv("Cek Pemahaman", "Negatif atau Positif? (klik untuk membuka)", [
  { prompt: "Aplikasi diet memberi peringatan saat kalori harian melewati target", answer: "Negatif", reason: "Mengembalikan ke standar." },
  { prompt: "Makin banyak pengguna → makin banyak ulasan → makin banyak pengguna baru", answer: "Positif", reason: "Memperkuat gerak sistem." },
  { prompt: "Mesin pabrik melambat otomatis saat produk cacat bertambah", answer: "Negatif", reason: "Mengurangi penyimpangan." },
  { prompt: "Bonus penjualan dinaikkan karena target terlampaui agar penjualan makin tinggi", answer: "Positif", reason: "Menambah kekuatan gerak." }]));
after("p2", "Data, Informasi, dan Pengetahuan", D.dikw);
after("p2", "Informasi", rv("Cek Pemahaman", "Data atau Informasi?", [
  { prompt: "“Biru”", answer: "Data", reason: "Fakta tanpa konteks." },
  { prompt: "“70% pembeli bulan ini memilih warna biru”", answer: "Informasi", reason: "Diolah (persentase) + konteks." },
  { prompt: "“42”", answer: "Data", reason: "Bisa ukuran sepatu, usia, apa saja." },
  { prompt: "Grafik jumlah mahasiswa baru per tahun 2020–2026", answer: "Informasi", reason: "Terorganisir dan bermakna." }]));
after("p3", "Kerangka Kerja Konseptual", D.kerangka);
after("p3", "Proses Kerja SI", D.ipo);
after("p3", "Tiga Peran Fundamental", D.segitiga);
after("p4", "Mengapa Ada Banyak Tipe SI", D.tipeSI);
after("p4", "Cara Membedakan MIS", { type: "table", label: "Tabel Interaktif", title: "Perbandingan Tujuh Tipe SI", headers: ["Tipe", "Pengguna utama", "Masukan", "Keluaran", "Contoh"],
  rows: [["TPS", "Staf operasional", "Transaksi", "Data terproses, update database", "Kasir, penggajian"], ["PCS", "Operator produksi", "Data sensor", "Pengendalian mesin", "Pabrik semen"], ["ECS", "Tim kerja", "Pesan, dokumen", "Komunikasi, kolaborasi", "Email, Zoom"], ["Expert System", "Pengguna awam", "Gejala/fakta", "Saran seperti ahli", "Pakar ternak"], ["MIS", "Manajer menengah", "Data dari TPS", "Laporan format tetap", "Laporan barang keluar-masuk"], ["DSS", "Manajer/analis", "Data + model", "Rekomendasi, simulasi", "Prediksi penjualan"], ["EIS", "Eksekutif/C-level", "Data internal & eksternal ringkas", "Grafik, KPI", "Dashboard direksi"]],
  modes: [{ label: "Alur data", target: "none", title: "TPS adalah sumber data", text: "Data transaksi dari <strong>TPS</strong> diolah <strong>MIS</strong> menjadi laporan, dipakai <strong>DSS</strong> untuk analisis, dan diringkas <strong>EIS</strong> untuk direksi." },
    { label: "Fokus DSS", target: "row", row: 5, title: "Masalah semi-terstruktur", text: "DSS cocok untuk keputusan yang tidak punya rumus pasti, misalnya menentukan harga produk baru." }] });
after("p5", "Lima Elemen CBIS", D.elemenCBIS);
after("p5", "Level CBIS", D.levelCBIS);
after("p5", "Model CBIS", D.modelCBIS);
after("p6", "Empat Generasi", D.generasi);
after("p6", "Jenis Komputer Menurut Ukuran", { type: "table", label: "Tabel Interaktif", title: "Mainframe vs Minicomputer vs Microcomputer", headers: ["Jenis", "Ukuran & kemampuan", "Pengguna", "Contoh pemakaian"],
  rows: [["Mainframe", "Terbesar, sangat kuat", "Multi-user (ribuan)", "Core banking, reservasi maskapai"], ["Minicomputer (midrange)", "Menengah", "Puluhan–ratusan", "Server departemen, perusahaan menengah"], ["Microcomputer (PC)", "Kecil", "Satu orang", "Desktop, laptop"]],
  modes: [{ label: "➕ Sekarang", target: "none", title: "Peran yang bergeser", text: "Fungsi minicomputer kini banyak digantikan <strong>server</strong> dan <strong>cloud</strong>; smartphone juga termasuk komputer mikro." }] });
after("p6", "Perangkat Lunak (Software)", D.softwareTree);
after("p7", "Hierarki Data", D.hierarki);
after("p7", "Masalah Pemrosesan File", D.fileVsDb);
after("p8", "Benang Merah", rv("Latihan Lisan", "Jelaskan dengan Kata-katamu, lalu Buka Jawabannya", [
  { prompt: "Apa hubungan level CBIS (P5) dengan tipe SI (P4)?", answer: "Sama polanya", reason: "Operational control = TPS, management control = MIS, strategic planning = EIS/DSS." },
  { prompt: "Mengapa data inconsistency (P7) merusak kualitas informasi (P2)?", answer: "Informasi jadi tidak akurat", reason: "Nilai yang berbeda untuk data yang sama membuat informasi tidak accurate dan tidak reliable." },
  { prompt: "Elemen CBIS (P5) mirip dengan apa di P3?", answer: "5 sumber daya SI O’Brien", reason: "People, hardware, software, data, network/telecommunication." },
  { prompt: "Feedback (P1) muncul lagi di mana?", answer: "Model lengkap SI O’Brien (P3)", reason: "Control of system performance: memantau dan memberi umpan balik." }]));
module.exports = M;
